if (options.TryGetTypeInfo<Person>(out JsonTypeInfo<Person>? found))
{
    Console.WriteLine($"TryGetTypeInfo<Person> → found ({found!.Type.Name})");
}

// Now use a restricted options instance (source-gen context with only Order)
var restricted = new JsonSerializerOptions { TypeInfoResolver = OrderContext.Default };

if (restricted.TryGetTypeInfo<Person>(out _))
{
    Console.WriteLine("TryGetTypeInfo<Person> on restricted → found (unexpected)");
}
else
{
    Console.WriteLine("TryGetTypeInfo<Person> on restricted → not available (expected)");
}

// Confirm Order *is* resolvable in that context
if (restricted.TryGetTypeInfo<Order>(out JsonTypeInfo<Order>? orderInfo))
{
    Console.WriteLine($"TryGetTypeInfo<Order> on restricted → found ({orderInfo!.Type.Name})");
}

